/* Feste Übersetzung der Lerninhalte (fa), maschinell erstellt, nicht von Muttersprachlern geprüft. Code bleibt unverändert. */
(function(r){"use strict";const f=r.SDAkademieFest=r.SDAkademieFest||{};(f["fa"]=f["fa"]||{})["webdesign"]={"Selektoren und Klassen":"انتخابگرها و کلاس‌ها","Mit CSS gezielt ein Element gestalten.":"با CSS یک عنصر را هدفمند طراحی کنید.","Klassen im HTML vergeben":"دادن کلاس در HTML","Eine Klasse ist wie ein Namensschild an einem Kleidungsstück. Du kannst mehreren Elementen dasselbe Schild geben. Im HTML steht dafür class. Im CSS beginnt der Klassenname mit einem Punkt. Eine Klasse verhält sich wie ein gemeinsames Etikett an mehreren Ordnern.":"یک کلاس مثل برچسب نام روی یک لباس است. می‌توانید به چند عنصر یک برچسب بدهید. در HTML برای این کار class نوشته می‌شود. در CSS نام کلاس با یک نقطه شروع می‌شود. یک کلاس مثل یک برچسب مشترک روی چند دوسیه رفتار می‌کند.","Die erste Zeile ist ein Absatz mit der Klasse hinweis.":"خط اول یک پاراگراف با کلاس hinweis است.","CSS-Klassenselektor schreiben":"نوشتن انتخابگر کلاس در CSS","Mit einem Punkt vor hinweis sprichst du nur passende Elemente an. Andere Absätze bleiben unverändert. Das ist nützlich für Warnungen oder Hinweise. Du kannst dieselbe Klasse mehrfach verwenden. So kannst du einen Hinweis später an einer einzigen CSS-Stelle verändern.":"با یک نقطه پیش از hinweis فقط عنصرهای مناسب را انتخاب می‌کنید. پاراگراف‌های دیگر بدون تغییر می‌مانند. این برای هشدارها یا راهنمایی‌ها مفید است. می‌توانید یک کلاس را چند بار به کار ببرید. به این ترتیب بعداً می‌توانید یک راهنمایی را در یک جای واحد CSS تغییر دهید.","Der Punkt kennzeichnet den Klassenselektor.":"نقطه انتخابگر کلاس را مشخص می‌کند.","ID und Klasse unterscheiden":"فرق ID و کلاس","Eine ID wird dagegen mit einer Raute ausgewählt. Sie sollte auf einer Seite nur einmal vorkommen. Klassen eignen sich für wiederkehrende Elemente. Prüfe die Schreibweise auf beiden Seiten. Prüfe die ID-Auswahl zunächst an einer einzelnen Überschrift.":"اما یک ID با علامهٔ # انتخاب می‌شود. در یک صفحه باید فقط یک بار بیاید. کلاس‌ها برای عنصرهای تکراری مناسب‌اند. املای نام را در هر دو طرف بررسی کنید. انتخاب ID را اول روی یک عنوان تنها امتحان کنید.","Die Raute wählt das Element mit id=\"kopf\".":"علامهٔ # عنصری را که id=\"kopf\" دارد انتخاب می‌کند.","Zwei Hinweise gleich gestalten":"طراحی یکسان دو راهنمایی","Ändere zuerst eine Klasse und beobachte die Vorschau. Danach gib einem zweiten Absatz dieselbe Klasse. Beide sollen die gleiche Farbe erhalten. So erkennst du den Vorteil gemeinsamer Regeln. Achte darauf, dass beide Absätze denselben Klassennamen tragen.":"اول یک کلاس را تغییر دهید و پیش‌نمایش را نگاه کنید. بعد به یک پاراگراف دوم همان کلاس را بدهید. هر دو باید یک رنگ بگیرند. به این ترتیب مزیت قاعده‌های مشترک را می‌بینید. دقت کنید که هر دو پاراگراف یک نام کلاس داشته باشند.","Der zweite Absatz erhält dieselbe Gestaltung.":"پاراگراف دوم همان طراحی را می‌گیرد.","Der Punkt vor einer Klasse fehlt":"نقطه پیش از کلاس کم است","Fehlt der Punkt vor dem Selektor, bleibt der Hinweis ohne gewünschte Farbe. Richtig ist `.hinweis { color: darkblue; }`, nicht `hinweis { color: darkblue; }`.":"اگر نقطه پیش از انتخابگر نباشد، راهنمایی رنگ دلخواه را نمی‌گیرد. درستش `.hinweis { color: darkblue; }` است، نه `hinweis { color: darkblue; }`.","class und CSS-Name stimmen nicht überein":"class و نام در CSS یکی نیستند","Wenn im HTML `class=\"hinweis\"` steht, aber CSS `.hinweise` auswählt, bleibt der Absatz unverändert. Verwende auf beiden Seiten denselben Namen: `<p class=\"hinweis\">Text</p>` und `.hinweis { color: darkblue; }`.":"اگر در HTML `class=\"hinweis\"` باشد اما CSS ‏`.hinweise` را انتخاب کند، پاراگراف بدون تغییر می‌ماند. در هر دو طرف یک نام به کار ببرید: `<p class=\"hinweis\">Text</p>` و `.hinweis { color: darkblue; }`.","Setze die Regeln dieser Lektion im Editor um und prüfe die Vorschau.":"قاعده‌های این درس را در ویرایشگر به کار ببرید و پیش‌نمایش را بررسی کنید.","Vergleiche die gezeigten Beispiele und prüfe die Schreibweise.":"مثال‌های نشان‌داده‌شده را مقایسه کنید و املا را بررسی کنید.","Die passende HTML-Struktur ist vorhanden.":"ساختار مناسب HTML وجود دارد.","Die passende Gestaltung oder Beschriftung ist vorhanden.":"طراحی یا برچسب مناسب وجود دارد.","Welcher Selektor wählt class=\"info\"?":"کدام انتخابگر class=\"info\" را انتخاب می‌کند؟","Bei „Welcher Selektor wählt class=\"info\"?“ ist „.info“ die passende Wahl, weil sie die gerade geübte Regel korrekt benennt.":"در سوال «کدام انتخابگر class=\"info\" را انتخاب می‌کند؟» گزینهٔ „.info“ درست است، چون قاعده‌ای را که همین حالا تمرین شد درست نام می‌برد.","Diese Angabe erfüllt die beschriebene Aufgabe nicht.":"این گزینه کار خواسته‌شده را انجام نمی‌دهد.","Diese Angabe passt zur beschriebenen Aufgabe.":"این گزینه با کار خواسته‌شده جور می‌آید.","Welche Aussage stimmt für Klassen?":"کدام جمله دربارهٔ کلاس‌ها درست است؟","Eine Klasse darf nur einmal vorkommen.":"یک کلاس فقط یک بار اجازه دارد بیاید.","Klassen ersetzen HTML.":"کلاس‌ها جای HTML را می‌گیرند.","Mehrere Elemente dürfen dieselbe Klasse haben.":"چند عنصر می‌توانند یک کلاس داشته باشند.","Für diese Aufgabe passt „Mehrere Elemente dürfen dieselbe Klasse haben.“; die beiden anderen Möglichkeiten erfüllen die gefragte Funktion nicht.":"برای این کار „چند عنصر می‌توانند یک کلاس داشته باشند.“ درست است؛ دو گزینهٔ دیگر کار خواسته‌شده را انجام نمی‌دهند.","Wie wählst du id=\"kopf\"?":"id=\"kopf\" را چطور انتخاب می‌کنید؟","Die Auswahl „#kopf“ löst die beschriebene Situation, während die Alternativen einen anderen Zweck haben.":"گزینهٔ „#kopf“ وضعیت توصیف‌شده را حل می‌کند، در حالی که گزینه‌های دیگر هدف دیگری دارند.","Ein Klassenname steht im HTML hinter `class` und im CSS hinter einem Punkt.":"نام یک کلاس در HTML بعد از `class` و در CSS بعد از یک نقطه می‌آید.","Mehrere Elemente können dieselbe Klasse tragen und dadurch gemeinsame Regeln nutzen.":"چند عنصر می‌توانند یک کلاس داشته باشند و به این ترتیب از قاعده‌های مشترک استفاده کنند.","Das Box-Modell verstehen":"فهمیدن مدل جعبه (Box Model)","Innenabstand, Rahmen und Außenabstand unterscheiden.":"فاصلهٔ داخلی، حاشیه و فاصلهٔ بیرونی را از هم جدا کنید.","Innenabstand am Paket erklären":"توضیح فاصلهٔ داخلی با یک بسته","Stell dir ein Paket im Karton vor. Der Inhalt ist dein Text. Das Polster entspricht padding. Die Kartonwand ist der border. Der Platz zum nächsten Karton ist margin. Ein Innenabstand macht den Text auch auf einem schmalen Display angenehmer lesbar.":"یک بسته را در یک کارتن تصور کنید. محتوا متن شماست. لایهٔ محافظ همان padding است. دیوار کارتن border است. فاصله تا کارتن بعدی margin است. فاصلهٔ داخلی متن را روی یک صفحهٔ باریک هم خواناتر می‌کند.","padding schafft Platz zwischen Text und Kartenrand.":"padding بین متن و لبهٔ کارت جا باز می‌کند.","Den sichtbaren Rahmen setzen":"گذاشتن حاشیهٔ قابل دید","Ein Rahmen macht die Kante sichtbar. Mit border kannst du Breite, Art und Farbe angeben. Ein Rahmen von zwei Pixeln bleibt sichtbar. Er umgibt den Innenabstand. Mit einer sichtbaren Linie erkennst du die Grenzen der Karte leichter.":"یک حاشیه لبه را قابل دید می‌کند. با border می‌توانید پهنا، نوع و رنگ را بنویسید. یک حاشیهٔ دو پیکسلی قابل دید می‌ماند. دور فاصلهٔ داخلی قرار می‌گیرد. با یک خط قابل دید مرزهای کارت را آسان‌تر می‌شناسید.","Die Regel zeichnet einen grauen Rahmen.":"این قاعده یک حاشیهٔ خاکستری رسم می‌کند.","Außenabstand zu Nachbarn":"فاصلهٔ بیرونی تا همسایه‌ها","margin liegt außerhalb des Rahmens. Es trennt die Karte von Nachbarn. Du kannst oben und unten verschiedene Abstände setzen. Verwechsle es nicht mit padding. Zwischen zwei Karten sorgt der Außenabstand für eine klare Trennung.":"margin بیرون از حاشیه است. کارت را از همسایه‌ها جدا می‌کند. می‌توانید برای بالا و پایین فاصله‌های مختلف بگذارید. آن را با padding اشتباه نگیرید. بین دو کارت فاصلهٔ بیرونی یک جدایی روشن ایجاد می‌کند.","Die erste Zahl betrifft oben und unten.":"عدد اول برای بالا و پایین است.","Breite mit border-box berechnen":"حساب کردن پهنا با border-box","Die Gesamtbreite kann sonst überraschend groß werden. box-sizing: border-box rechnet padding und border in die eingestellte Breite ein. Das hilft bei kleinen Bildschirmen. Teste es mit einer Karte. Prüfe die Kartenbreite im Browser, wenn du padding erhöhst.":"در غیر آن پهنای کل ممکن است به‌طور غیرمنتظره بزرگ شود. box-sizing: border-box ‏padding و border را در پهنای تعیین‌شده حساب می‌کند. این در صفحه‌های کوچک کمک می‌کند. آن را با یک کارت امتحان کنید. وقتی padding را بیشتر می‌کنید، پهنای کارت را در براوزر بررسی کنید.","Die Karte bleibt innerhalb ihres Containers.":"کارت داخل ظرف خود می‌ماند.","margin mit padding verwechselt":"margin با padding اشتباه گرفته شد","Wenn der Text direkt am Rahmen klebt, fehlt Innenabstand. Schreibe `.karte { padding: 16px; }` statt nur `margin: 16px`, denn margin liegt außerhalb der Karte.":"اگر متن مستقیم به حاشیه چسپیده باشد، فاصلهٔ داخلی کم است. به جای فقط `margin: 16px` بنویسید `.karte { padding: 16px; }`، چون margin بیرون از کارت است.","border ohne Linienart geschrieben":"border بدون نوع خط نوشته شد","Wenn keine Umrandung erscheint, wurde oft die Linienart ausgelassen. Vollständig lautet die Regel `.karte { border: 2px solid gray; }`; `border: 2px gray` reicht nicht.":"اگر هیچ حاشیه‌ای دیده نشود، اغلب نوع خط حذف شده است. قاعدهٔ کامل `.karte { border: 2px solid gray; }` است؛ `border: 2px gray` کافی نیست.","Was schafft Abstand innerhalb des Rahmens?":"چه چیزی داخل حاشیه فاصله ایجاد می‌کند؟","Bei „Was schafft Abstand innerhalb des Rahmens?“ ist „padding“ die passende Wahl, weil sie die gerade geübte Regel korrekt benennt.":"در سوال «چه چیزی داخل حاشیه فاصله ایجاد می‌کند؟» گزینهٔ „padding“ درست است، چون قاعده‌ای را که همین حالا تمرین شد درست نام می‌برد.","Was liegt außerhalb des Rahmens?":"چه چیزی بیرون از حاشیه است؟","Für diese Aufgabe passt „margin“; die beiden anderen Möglichkeiten erfüllen die gefragte Funktion nicht.":"برای این کار „margin“ درست است؛ دو گزینهٔ دیگر کار خواسته‌شده را انجام نمی‌دهند.","Welche Einstellung erleichtert feste Breiten?":"کدام تنظیم پهناهای ثابت را آسان می‌کند؟","Die Auswahl „box-sizing: border-box“ löst die beschriebene Situation, während die Alternativen einen anderen Zweck haben.":"گزینهٔ „box-sizing: border-box“ وضعیت توصیف‌شده را حل می‌کند، در حالی که گزینه‌های دیگر هدف دیگری دارند.","padding liegt innerhalb, margin außerhalb der Rahmenlinie.":"padding داخل و margin بیرون از خط حاشیه است.","Mit `box-sizing: border-box` bleiben Rahmen und Innenabstand in der festgelegten Breite.":"با `box-sizing: border-box` حاشیه و فاصلهٔ داخلی در پهنای تعیین‌شده می‌مانند.","Flexbox für eine Navigation":"Flexbox برای یک منو","Elemente nebeneinander und untereinander anordnen.":"عنصرها را کنار هم و زیر هم قرار دهید.","Navigation als Flex-Container":"منو به عنوان ظرف Flex","Eine Reihe von Stühlen lässt sich nebeneinander stellen. Flexbox ordnet HTML-Elemente ähnlich an. Die Einstellung kommt auf den gemeinsamen Container. Seine direkten Kinder werden flexibel angeordnet. Die Navigation ist der gemeinsame Behälter für ihre Links.":"یک ردیف چوکی را می‌شود کنار هم گذاشت. Flexbox عنصرهای HTML را به همین شکل مرتب می‌کند. این تنظیم روی ظرف مشترک گذاشته می‌شود. فرزندان مستقیم آن به‌طور انعطاف‌پذیر مرتب می‌شوند. منو ظرف مشترک لینک‌هایش است.","display: flex aktiviert die flexible Reihe.":"display: flex ردیف انعطاف‌پذیر را فعال می‌کند.","Abstände zwischen Links":"فاصله بین لینک‌ها","Mit gap bestimmst du den Abstand zwischen den Einträgen. Du brauchst dann nicht für jeden Link einen eigenen Außenabstand. Das macht die Navigation übersichtlich. Der Abstand gilt gleichmäßig. Der Zwischenraum soll auch bei einem längeren Linknamen erhalten bleiben.":"با gap فاصلهٔ بین عنصرها را تعیین می‌کنید. در آن صورت برای هر لینک به یک فاصلهٔ بیرونی جدا نیاز ندارید. این کار منو را مرتب می‌کند. فاصله یکسان اعمال می‌شود. این فاصله باید با یک نام لینک طولانی‌تر هم باقی بماند.","gap trennt die Links um zwölf Pixel.":"gap لینک‌ها را دوازده پیکسل از هم جدا می‌کند.","Elemente auf der Hauptachse":"عنصرها روی محور اصلی","justify-content steuert die Verteilung in der Hauptachse. Mit space-between entstehen Abstände zwischen den Einträgen. align-items richtet Elemente quer dazu aus. Beide Eigenschaften erfüllen verschiedene Aufgaben. Vergleiche die Verteilung links und rechts im breiten Fenster.":"justify-content پخش شدن روی محور اصلی را کنترول می‌کند. با space-between بین عنصرها فاصله ایجاد می‌شود. align-items عنصرها را در جهت عمود بر آن تنظیم می‌کند. هر دو ویژگی کارهای مختلفی دارند. پخش شدن را در چپ و راست یک پنجرهٔ پهن مقایسه کنید.","Die Links verteilen sich über die Breite.":"لینک‌ها در تمام پهنا پخش می‌شوند.","Umbruch bei wenig Platz":"رفتن به خط بعد وقتی جا کم است","Auf schmalen Geräten passt eine lange Reihe nicht immer. flex-wrap erlaubt den Umbruch in eine weitere Zeile. So bleiben Links erreichbar. Probiere verschiedene Fensterbreiten aus. Bei 320 Pixeln sollten alle Navigationspunkte erreichbar bleiben.":"در دستگاه‌های باریک یک ردیف طولانی همیشه جا نمی‌شود. flex-wrap اجازه می‌دهد عنصرها به یک خط دیگر بروند. به این ترتیب لینک‌ها در دسترس می‌مانند. پهناهای مختلف پنجره را امتحان کنید. در 320 پیکسل باید همهٔ گزینه‌های منو در دسترس بمانند.","Einträge dürfen in die nächste Zeile wechseln.":"عنصرها اجازه دارند به خط بعدی بروند.","display: flex auf den Links statt dem Container":"display: flex روی لینک‌ها به جای ظرف","Stehen die Links trotz `display: flex` untereinander, wurde die Regel möglicherweise auf einzelne Links statt auf `nav` gesetzt. Nutze `nav { display: flex; }` für ihren gemeinsamen Container.":"اگر لینک‌ها با وجود `display: flex` زیر هم باشند، شاید قاعده روی تک‌تک لینک‌ها گذاشته شده نه روی `nav`. برای ظرف مشترک آن‌ها `nav { display: flex; }` را به کار ببرید.","flex-wrap vergessen und Links abgeschnitten":"فراموش کردن flex-wrap و بریده شدن لینک‌ها","Wenn die Navigation rechts aus dem Handybildschirm ragt, dürfen die Einträge nicht umbrechen. Ergänze `nav { display: flex; flex-wrap: wrap; gap: 12px; }` und prüfe die schmale Ansicht.":"اگر منو در موبایل از طرف راست صفحه بیرون بزند، عنصرها اجازهٔ رفتن به خط بعد را ندارند. `nav { display: flex; flex-wrap: wrap; gap: 12px; }` را اضافه کنید و نمای باریک را بررسی کنید.","Welche Eigenschaft aktiviert Flexbox?":"کدام ویژگی Flexbox را فعال می‌کند؟","Bei „Welche Eigenschaft aktiviert Flexbox?“ ist „display: flex“ die passende Wahl, weil sie die gerade geübte Regel korrekt benennt.":"در سوال «کدام ویژگی Flexbox را فعال می‌کند؟» گزینهٔ „display: flex“ درست است، چون قاعده‌ای را که همین حالا تمرین شد درست نام می‌برد.","Was erzeugt Abstand zwischen Flex-Kindern?":"چه چیزی بین فرزندان Flex فاصله ایجاد می‌کند؟","Für diese Aufgabe passt „gap“; die beiden anderen Möglichkeiten erfüllen die gefragte Funktion nicht.":"برای این کار „gap“ درست است؛ دو گزینهٔ دیگر کار خواسته‌شده را انجام نمی‌دهند.","Was erlaubt den Zeilenumbruch?":"چه چیزی اجازهٔ رفتن به خط بعد را می‌دهد؟","Die Auswahl „flex-wrap: wrap“ löst die beschriebene Situation, während die Alternativen einen anderen Zweck haben.":"گزینهٔ „flex-wrap: wrap“ وضعیت توصیف‌شده را حل می‌کند، در حالی که گزینه‌های دیگر هدف دیگری دارند.","Flexbox wird auf dem gemeinsamen Eltern-Element eingeschaltet.":"Flexbox روی عنصر والد مشترک روشن می‌شود.","`flex-wrap: wrap` erlaubt bei Platzmangel eine weitere Zeile.":"`flex-wrap: wrap` وقتی جا کم است یک خط دیگر را اجازه می‌دهد.","Grid für Seitenbereiche":"Grid برای بخش‌های صفحه","Eine Seite in Spalten und Zeilen aufteilen.":"یک صفحه را به ستون‌ها و ردیف‌ها تقسیم کنید.","Ein Raster aktivieren":"فعال کردن یک شبکه","Ein Kalender hat Spalten und Zeilen. CSS Grid nutzt dieselbe Idee für Webseiten. Du aktivierst Grid auf einem Container. Danach verteilst du die Kinder in ein Raster. Das Raster ähnelt einem Regal mit mehreren Fächern.":"یک تقویم ستون‌ها و ردیف‌ها دارد. CSS Grid همین ایده را برای ویب‌سایت‌ها به کار می‌برد. Grid را روی یک ظرف فعال می‌کنید. بعد فرزندان را در یک شبکه پخش می‌کنید. این شبکه شبیه یک الماری با چند خانه است.","Grid wird für alle direkten Kinder aktiviert.":"Grid برای همهٔ فرزندان مستقیم فعال می‌شود.","Zwei gleich breite Spalten":"دو ستون هم‌پهنا","grid-template-columns bestimmt die Spalten. Mit 1fr 1fr entstehen zwei gleich breite Spalten. fr bezeichnet einen Anteil des freien Platzes. Das Raster passt sich an die Containerbreite an. Die beiden Spalten erhalten jeweils die Hälfte des freien Raums.":"grid-template-columns ستون‌ها را تعیین می‌کند. با 1fr 1fr دو ستون هم‌پهنا ساخته می‌شوند. fr یعنی سهمی از جای خالی. شبکه خودش را با پهنای ظرف هماهنگ می‌کند. هر کدام از دو ستون نیمی از جای خالی را می‌گیرد.","Zwei gleiche Anteile ergeben zwei Spalten.":"دو سهم برابر دو ستون می‌سازند.","Zwischenräume mit gap":"فاصله‌ها با gap","Mit gap schaffst du Luft zwischen den Feldern. Das gilt für Zeilen und Spalten. Einzelne Karten benötigen keine eigenen Ränder. Das Raster bleibt dadurch regelmäßig. Ein Abstand zwischen den Fächern verbessert die Übersicht.":"با gap بین خانه‌ها فاصله ایجاد می‌کنید. این برای ردیف‌ها و ستون‌ها صدق می‌کند. تک‌تک کارت‌ها به حاشیهٔ جداگانه نیاز ندارند. به این ترتیب شبکه منظم می‌ماند. فاصله بین خانه‌ها نظم را بهتر می‌کند.","Zwischen den Karten liegen sechzehn Pixel.":"بین کارت‌ها شانزده پیکسل فاصله است.","Einspaltige Handyansicht":"نمای یک‌ستونی موبایل","Auf einem schmalen Handy kann eine Spalte besser sein. Ein Raster mit nur 1fr stapelt die Karten. Du kannst die Spalten später per Media Query ändern. Prüfe die Lesbarkeit bei 320 Pixeln. Einspaltige Karten sind auf kleinen Handys leichter zu lesen.":"در یک موبایل باریک یک ستون ممکن است بهتر باشد. شبکه‌ای فقط با 1fr کارت‌ها را زیر هم می‌گذارد. می‌توانید ستون‌ها را بعداً با Media Query تغییر دهید. خوانایی را در 320 پیکسل بررسی کنید. کارت‌های یک‌ستونی در موبایل‌های کوچک آسان‌تر خوانده می‌شوند.","Alle Karten stehen untereinander.":"همهٔ کارت‌ها زیر هم قرار دارند.","grid-template-columns ohne display: grid":"grid-template-columns بدون display: grid","Wenn die Karten nicht in Spalten stehen, ist nur `grid-template-columns` gesetzt. Ergänze am Eltern-Element `main { display: grid; grid-template-columns: 1fr 1fr; }`.":"اگر کارت‌ها در ستون‌ها نباشند، فقط `grid-template-columns` گذاشته شده است. روی عنصر والد `main { display: grid; grid-template-columns: 1fr 1fr; }` را اضافه کنید.","Feste Spalten zu breit für das Handy":"ستون‌های ثابت برای موبایل خیلی پهن","Wenn zwei feste Spalten auf dem Handy über den Rand gehen, ist das Raster zu breit. Beginne mit `main { grid-template-columns: 1fr; }` und schalte zwei Spalten erst für größere Ansichten ein.":"اگر دو ستون ثابت در موبایل از لبه بیرون بروند، شبکه خیلی پهن است. با `main { grid-template-columns: 1fr; }` شروع کنید و دو ستون را فقط برای نماهای بزرگ‌تر روشن کنید.","Welche Eigenschaft legt Grid-Spalten fest?":"کدام ویژگی ستون‌های Grid را تعیین می‌کند؟","Bei „Welche Eigenschaft legt Grid-Spalten fest?“ ist „grid-template-columns“ die passende Wahl, weil sie die gerade geübte Regel korrekt benennt.":"در سوال «کدام ویژگی ستون‌های Grid را تعیین می‌کند؟» گزینهٔ „grid-template-columns“ درست است، چون قاعده‌ای را که همین حالا تمرین شد درست نام می‌برد.","Was bedeutet 1fr 1fr?":"1fr 1fr یعنی چه؟","Zwei gleiche Spalten":"دو ستون برابر","Zwei feste Pixel":"دو پیکسل ثابت","Eine einzige Zeile":"فقط یک ردیف","Für diese Aufgabe passt „Zwei gleiche Spalten“; die beiden anderen Möglichkeiten erfüllen die gefragte Funktion nicht.":"برای این کار „دو ستون برابر“ درست است؛ دو گزینهٔ دیگر کار خواسته‌شده را انجام نمی‌دهند.","Welche Regel aktiviert Grid?":"کدام قاعده Grid را فعال می‌کند؟","Die Auswahl „display: grid“ löst die beschriebene Situation, während die Alternativen einen anderen Zweck haben.":"گزینهٔ „display: grid“ وضعیت توصیف‌شده را حل می‌کند، در حالی که گزینه‌های دیگر هدف دیگری دارند.","Grid teilt den Platz in definierte Spalten und Zeilen.":"Grid جا را به ستون‌ها و ردیف‌های تعریف‌شده تقسیم می‌کند.","Eine einzelne `1fr`-Spalte ist für kleine Ansichten oft leichter lesbar.":"یک ستون تنهای `1fr` برای نماهای کوچک اغلب خواناتر است.","Responsive mit Media Queries":"واکنش‌گرا با Media Query","Gestaltung an schmale Bildschirme anpassen.":"طراحی را با صفحه‌های باریک هماهنگ کنید.","Bildschirmbreite abfragen":"پرسیدن پهنای صفحه","Ein Stadtplan wird auf dem Handy anders gefaltet als auf dem Tisch. Eine Webseite braucht ebenfalls verschiedene Anordnungen. Eine Media Query prüft die Bildschirmbreite. Danach gelten passende CSS-Regeln. Die Bildschirmbreite kann sich beim Drehen eines Handys verändern.":"یک نقشهٔ شهر در موبایل جور دیگری تا می‌شود تا روی میز. یک ویب‌سایت هم به چیدمان‌های مختلف نیاز دارد. یک Media Query پهنای صفحه را بررسی می‌کند. بعد قاعده‌های مناسب CSS اعمال می‌شوند. پهنای صفحه ممکن است با چرخاندن موبایل تغییر کند.","Die Regel gilt bis zu einer Breite von 600 Pixeln.":"این قاعده تا پهنای 600 پیکسل اعمال می‌شود.","Bilder flexibel halten":"انعطاف‌پذیر نگه داشتن عکس‌ها","Beginne mit einer gut lesbaren Handyansicht. Verwende Breiten in Prozent statt überall feste Pixel. Große Bilder dürfen nicht aus dem Bildschirm ragen. max-width: 100% hilft dabei. Ein Foto soll nicht über die sichtbare Seitenkante hinauslaufen.":"با یک نمای موبایل خوب خوانا شروع کنید. به جای پیکسل‌های ثابت در همه جا، پهنا را با فیصد بنویسید. عکس‌های بزرگ نباید از صفحه بیرون بزنند. max-width: 100% به این کار کمک می‌کند. یک عکس نباید از لبهٔ قابل دید صفحه بیرون برود.","Das Bild überschreitet seinen verfügbaren Platz nicht.":"عکس از جای در دسترس خود بیشتر نمی‌شود.","Spalten ab 700 Pixeln":"ستون‌ها از 700 پیکسل به بالا","Für größere Bildschirme kannst du zusätzliche Spalten aktivieren. Eine Media Query mit min-width gilt ab einer bestimmten Breite. Die Grundgestaltung bleibt erhalten. Nur die Unterschiede werden überschrieben. Die zweite Spalte ist nur auf ausreichend breiten Geräten sinnvoll.":"برای صفحه‌های بزرگ‌تر می‌توانید ستون‌های اضافی را فعال کنید. یک Media Query با min-width از یک پهنای معین به بالا اعمال می‌شود. طراحی پایه باقی می‌ماند. فقط فرق‌ها بازنویسی می‌شوند. ستون دوم فقط در دستگاه‌هایی که به اندازهٔ کافی پهن هستند معقول است.","Ab 700 Pixeln gibt es zwei Spalten.":"از 700 پیکسل به بالا دو ستون وجود دارد.","320-Pixel-Ansicht kontrollieren":"بررسی نمای 320 پیکسلی","Teste nicht nur auf deinem eigenen Handy. Bei 320 Pixeln sind lange Wörter besonders kritisch. Bei 390 Pixeln sollten Knöpfe gut erreichbar sein. Am PC darf die Textzeile nicht endlos breit werden. Teste lange Vereinsnamen zusätzlich mit vergrößerter Schrift.":"فقط روی موبایل خودتان آزمایش نکنید. در 320 پیکسل کلمه‌های طولانی به‌خصوص مشکل‌سازند. در 390 پیکسل دکمه‌ها باید آسان در دسترس باشند. در کمپیوتر خط متن نباید بی‌پایان پهن شود. نام‌های طولانی انجمن را هم با فونت بزرگ‌شده آزمایش کنید.","Lange Wörter können umgebrochen werden.":"کلمه‌های طولانی می‌توانند شکسته شوند.","min-width und max-width verwechselt":"اشتباه گرفتن min-width و max-width","Wenn die Handyregel auf einem großen Monitor statt auf einem kleinen Bildschirm wirkt, wurden `min-width` und `max-width` vertauscht. Für höchstens 600 Pixel nutze `@media (max-width: 600px) { ... }`.":"اگر قاعدهٔ موبایل به جای یک صفحهٔ کوچک روی یک مانیتور بزرگ اثر کند، `min-width` و `max-width` جابه‌جا شده‌اند. برای حداکثر 600 پیکسل `@media (max-width: 600px) { ... }` را به کار ببرید.","Feste Breiten erzeugen horizontales Scrollen":"پهناهای ثابت اسکرول افقی ایجاد می‌کنند","Wenn ein breites Bild seitliches Scrollen verursacht, ist seine Breite nicht begrenzt. Ergänze `img { max-width: 100%; height: auto; }`, damit es in den verfügbaren Platz passt.":"اگر یک عکس پهن اسکرول به پهلو ایجاد کند، پهنای آن محدود نشده است. `img { max-width: 100%; height: auto; }` را اضافه کنید تا در جای در دسترس جا شود.","Welche Media Query gilt bei 500 Pixeln?":"کدام Media Query در 500 پیکسل اعمال می‌شود؟","Bei „Welche Media Query gilt bei 500 Pixeln?“ ist „@media (max-width: 600px)“ die passende Wahl, weil sie die gerade geübte Regel korrekt benennt.":"در سوال «کدام Media Query در 500 پیکسل اعمال می‌شود؟» گزینهٔ „@media (max-width: 600px)“ درست است، چون قاعده‌ای را که همین حالا تمرین شد درست نام می‌برد.","Was verhindert zu breite Bilder?":"چه چیزی از عکس‌های خیلی پهن جلوگیری می‌کند؟","Für diese Aufgabe passt „max-width: 100%“; die beiden anderen Möglichkeiten erfüllen die gefragte Funktion nicht.":"برای این کار „max-width: 100%“ درست است؛ دو گزینهٔ دیگر کار خواسته‌شده را انجام نمی‌دهند.","Was bedeutet mobile first?":"mobile first یعنی چه؟","Nur für Handys entwickeln":"فقط برای موبایل ساختن","Alle Geräte gleich darstellen":"همهٔ دستگاه‌ها را یکسان نشان دادن","Zuerst die schmale Ansicht gestalten":"اول نمای باریک را طراحی کردن","Die Auswahl „Zuerst die schmale Ansicht gestalten“ löst die beschriebene Situation, während die Alternativen einen anderen Zweck haben.":"گزینهٔ „اول نمای باریک را طراحی کردن“ وضعیت توصیف‌شده را حل می‌کند، در حالی که گزینه‌های دیگر هدف دیگری دارند.","`max-width` begrenzt Regeln nach oben, `min-width` aktiviert sie ab einer Breite.":"`max-width` قاعده‌ها را از بالا محدود می‌کند و `min-width` آن‌ها را از یک پهنا به بالا فعال می‌کند.","Responsive Seiten bleiben auch bei 320 Pixeln ohne waagerechtes Scrollen nutzbar.":"صفحه‌های واکنش‌گرا در 320 پیکسل هم بدون اسکرول افقی قابل استفاده می‌مانند.","Formulare richtig bauen":"ساختن درست فورم‌ها","Beschriftungen, Eingabetypen und Prüfung einsetzen.":"برچسب‌ها، نوع ورودی و بررسی را به کار ببرید.","Beschriftung und Eingabe koppeln":"وصل کردن برچسب و ورودی","Ein Papierformular hat zu jedem Feld eine Überschrift. Im Web übernimmt label diese Aufgabe. Die Beschriftung sagt, was eingegeben werden soll. Mit for und id verbindest du beide Teile. Eine klare Beschriftung hilft auch Menschen mit Vorleseprogramm.":"یک فورم کاغذی برای هر خانه یک عنوان دارد. در ویب label این کار را انجام می‌دهد. برچسب می‌گوید چه چیزی باید وارد شود. با for و id هر دو بخش را به هم وصل می‌کنید. یک برچسب روشن به کسانی که از برنامهٔ صفحه‌خوان استفاده می‌کنند هم کمک می‌کند.","for und id haben denselben Wert.":"for و id مقدار یکسان دارند.","Eingabetypen bewusst wählen":"انتخاب آگاهانهٔ نوع ورودی","Ein Eingabetyp hilft dem Browser bei der Bedienung. type=\"email\" zeigt auf Handys oft eine passende Tastatur. type=\"tel\" eignet sich für Telefonnummern. Ein guter Typ macht das Formular leichter. Der Eingabetyp kann auf dem Handy die passende Tastatur öffnen.":"نوع ورودی به براوزر در کار کمک می‌کند. type=\"email\" در موبایل اغلب یک کیبورد مناسب نشان می‌دهد. type=\"tel\" برای شماره‌های تیلفون مناسب است. یک نوع خوب فورم را آسان‌تر می‌کند. نوع ورودی می‌تواند در موبایل کیبورد مناسب را باز کند.","Der Browser erkennt ein Feld für Telefonnummern.":"براوزر یک خانه برای شماره‌های تیلفون را می‌شناسد.","Pflichtfelder kennzeichnen":"علامت زدن خانه‌های اجباری","required kennzeichnet ein Pflichtfeld. Der Browser kann vor dem Absenden auf fehlende Angaben hinweisen. Das ersetzt keine sichere Prüfung auf einem Server. Für eine reine Übung reicht die Browserprüfung. Ein Pflichtfeld braucht zusätzlich eine verständliche Fehlermeldung.":"required یک خانهٔ اجباری را مشخص می‌کند. براوزر می‌تواند پیش از فرستادن، معلومات ناموجود را یادآوری کند. این جای یک بررسی مطمئن روی سرور را نمی‌گیرد. برای یک تمرین ساده بررسی براوزر کافی است. یک خانهٔ اجباری به یک پیام خطای قابل فهم هم نیاز دارد.","Das Feld muss ausgefüllt werden und eine E-Mail-Form haben.":"این خانه باید پر شود و شکل یک ایمیل را داشته باشد.","Senden-Knopf festlegen":"تعیین دکمهٔ فرستادن","Ein Button mit type=\"submit\" sendet das Formular ab. Ein Button mit type=\"button\" löst das nicht automatisch aus. Wähle den Typ bewusst. Teste das Formular auch mit der Tastatur. Kontrolliere, ob die Eingabe auch ohne Maus abgeschickt werden kann.":"یک دکمه با type=\"submit\" فورم را می‌فرستد. یک دکمه با type=\"button\" این کار را خودکار انجام نمی‌دهد. نوع را آگاهانه انتخاب کنید. فورم را با کیبورد هم آزمایش کنید. بررسی کنید که آیا ورودی بدون موس هم فرستاده می‌شود.","Der Knopf ist als Senden-Knopf markiert.":"دکمه به عنوان دکمهٔ فرستادن علامت خورده است.","label ohne passende id":"label بدون id مناسب","Wenn ein Klick auf die Beschriftung das Eingabefeld nicht aktiviert, passen `for` und `id` nicht zusammen. Korrekt: `<label for=\"mail\">E-Mail</label><input id=\"mail\" type=\"email\">`.":"اگر کلیک روی برچسب خانهٔ ورودی را فعال نکند، `for` و `id` با هم جور نیستند. درست: `<label for=\"mail\">E-Mail</label><input id=\"mail\" type=\"email\">`.","required mit sicherer Serverprüfung verwechselt":"اشتباه گرفتن required با بررسی مطمئن سرور","Wenn ein leeres Pflichtfeld ohne Hinweis gesendet werden kann, fehlt möglicherweise `required`. Nutze `<input id=\"mail\" type=\"email\" required>`; prüfe sensible Daten zusätzlich auf einem Server.":"اگر یک خانهٔ اجباری خالی بدون پیام فرستاده شود، شاید `required` کم باشد. از `<input id=\"mail\" type=\"email\" required>` استفاده کنید؛ داده‌های حساس را روی سرور هم بررسی کنید.","Was verbindet label mit input?":"چه چیزی label را با input وصل می‌کند؟","class und style":"class و style","for und id":"for و id","name und value":"name و value","Bei „Was verbindet label mit input?“ ist „for und id“ die passende Wahl, weil sie die gerade geübte Regel korrekt benennt.":"در سوال «چه چیزی label را با input وصل می‌کند؟» گزینهٔ „for و id“ درست است، چون قاعده‌ای را که همین حالا تمرین شد درست نام می‌برد.","Welcher Typ passt zur E-Mail-Adresse?":"کدام نوع برای آدرس ایمیل مناسب است؟","Für diese Aufgabe passt „email“; die beiden anderen Möglichkeiten erfüllen die gefragte Funktion nicht.":"برای این کار „email“ درست است؛ دو گزینهٔ دیگر کار خواسته‌شده را انجام نمی‌دهند.","Was kennzeichnet ein Pflichtfeld?":"چه چیزی یک خانهٔ اجباری را مشخص می‌کند؟","Die Auswahl „required“ löst die beschriebene Situation, während die Alternativen einen anderen Zweck haben.":"گزینهٔ „required“ وضعیت توصیف‌شده را حل می‌کند، در حالی که گزینه‌های دیگر هدف دیگری دارند.","`label for` und `input id` müssen genau übereinstimmen.":"`label for` و `input id` باید دقیقاً یکی باشند.","`required` hilft bei der Browserprüfung, ersetzt aber keine serverseitige Validierung.":"`required` به بررسی براوزر کمک می‌کند، اما جای بررسی سمت سرور را نمی‌گیرد.","Barrierefreiheit im Alltag":"دسترسی‌پذیری در زندگی روزمره","Eine Webseite mit Tastatur und Vorleseprogramm bedienen.":"یک ویب‌سایت را با کیبورد و برنامهٔ صفحه‌خوان به کار ببرید.","Echte Schaltflächen einsetzen":"استفاده از دکمه‌های واقعی","Ein Gebäude braucht einen Eingang für verschiedene Menschen. Eine Webseite soll ebenso zugänglich sein. Verwende dafür echte HTML-Elemente. Ein button ist besser als ein klickbarer Absatz. Ein echter Knopf besitzt bereits eine passende Tastaturfunktion.":"یک ساختمان برای آدم‌های مختلف به یک دروازه نیاز دارد. یک ویب‌سایت هم باید به همین شکل در دسترس باشد. برای این کار عنصرهای واقعی HTML را به کار ببرید. یک button از یک پاراگراف قابل کلیک بهتر است. یک دکمهٔ واقعی از قبل عملکرد مناسب کیبورد را دارد.","Der Browser erkennt einen bedienbaren Knopf.":"براوزر یک دکمهٔ قابل استفاده را می‌شناسد.","Überschriften sinnvoll ordnen":"مرتب کردن معقول عنوان‌ها","Überschriften geben dem Inhalt eine klare Ordnung. Beginne mit einer passenden h1. Darunter folgen h2 für größere Abschnitte. Vorleseprogramme können so leichter navigieren. Die Überschriftenstruktur ist wie das Inhaltsverzeichnis eines Buches.":"عنوان‌ها به محتوا یک نظم روشن می‌دهند. با یک h1 مناسب شروع کنید. زیر آن h2 برای بخش‌های بزرگ‌تر می‌آید. به این ترتیب برنامه‌های صفحه‌خوان آسان‌تر حرکت می‌کنند. ساختار عنوان‌ها مثل فهرست مطالب یک کتاب است.","Die zweite Überschrift gehört zum Abschnitt Kontakt.":"عنوان دوم به بخش Kontakt تعلق دارد.","Alternativtexte für Bilder":"متن جایگزین برای عکس‌ها","Ein Bild braucht einen sinnvollen Alternativtext. Der alt-Text beschreibt wichtige Bildinformationen. Ein rein dekoratives Bild darf alt=\"\" haben. Schreibe nicht nur das Wort Bild. Ein Alternativtext soll den wichtigen Bildinhalt knapp benennen.":"یک عکس به یک متن جایگزین معقول نیاز دارد. متن alt معلومات مهم عکس را توصیف می‌کند. یک عکس فقط تزئینی می‌تواند alt=\"\" داشته باشد. فقط کلمهٔ «عکس» را ننویسید. یک متن جایگزین باید محتوای مهم عکس را کوتاه نام ببرد.","Der Alternativtext nennt den Inhalt des Logos.":"متن جایگزین محتوای لوگو را نام می‌برد.","Fehler auch als Text melden":"گزارش خطا به شکل متن هم","Farbe allein reicht nicht für Fehlermeldungen. Zeige zusätzlich einen verständlichen Text. Achte auf lesbaren Kontrast. Prüfe, ob du die Seite mit Tab und Enter bedienen kannst. Eine Meldung darf nicht allein durch ihre Farbe verständlich sein.":"رنگ به تنهایی برای پیام‌های خطا کافی نیست. یک متن قابل فهم هم نشان دهید. به کنتراست خوانا توجه کنید. بررسی کنید که آیا می‌توانید صفحه را با Tab و Enter به کار ببرید. یک پیام نباید فقط از راه رنگش قابل فهم باشد.","Der Status kann auch vorgelesen werden.":"این وضعیت را می‌شود بلند هم خواند.","Klickbarer div statt echter Schaltfläche":"div قابل کلیک به جای دکمهٔ واقعی","Wenn ein Element per Tab-Taste nicht erreichbar ist, wurde eventuell ein klickbarer `div` verwendet. Setze für Aktionen `<button type=\"button\">Menü öffnen</button>` ein.":"اگر یک عنصر با کلید Tab در دسترس نباشد، شاید یک `div` قابل کلیک به کار رفته باشد. برای کارها `<button type=\"button\">Menü öffnen</button>` را به کار ببرید.","Bild ohne passenden Alternativtext":"عکس بدون متن جایگزین مناسب","Wenn ein Vorleseprogramm das wichtige Logo nicht beschreibt, fehlt der Alternativtext. Ergänze `<img src=\"logo.svg\" alt=\"Logo des Vereins\">`; dekorative Bilder erhalten `alt=\"\"`.":"اگر یک برنامهٔ صفحه‌خوان لوگوی مهم را توصیف نکند، متن جایگزین کم است. `<img src=\"logo.svg\" alt=\"Logo des Vereins\">` را اضافه کنید؛ عکس‌های تزئینی `alt=\"\"` می‌گیرند.","Welches Element ist ein echter Knopf?":"کدام عنصر یک دکمهٔ واقعی است؟","Bei „Welches Element ist ein echter Knopf?“ ist „<button>OK</button>“ die passende Wahl, weil sie die gerade geübte Regel korrekt benennt.":"در سوال «کدام عنصر یک دکمهٔ واقعی است؟» گزینهٔ „<button>OK</button>“ درست است، چون قاعده‌ای را که همین حالا تمرین شد درست نام می‌برد.","Was gehört zu einem wichtigen Bild?":"چه چیزی به یک عکس مهم تعلق دارد؟","Nur eine Farbe":"فقط یک رنگ","Ein sinnvoller alt-Text":"یک متن alt معقول","Ein versteckter Link":"یک لینک پنهان","Für diese Aufgabe passt „Ein sinnvoller alt-Text“; die beiden anderen Möglichkeiten erfüllen die gefragte Funktion nicht.":"برای این کار „یک متن alt معقول“ درست است؛ دو گزینهٔ دیگر کار خواسته‌شده را انجام نمی‌دهند.","Was hilft bei einer Fehlermeldung?":"چه چیزی به یک پیام خطا کمک می‌کند؟","Nur rote Farbe":"فقط رنگ سرخ","Nur ein Symbol":"فقط یک نشانه","Text zusätzlich zur Farbe":"متن علاوه بر رنگ","Die Auswahl „Text zusätzlich zur Farbe“ löst die beschriebene Situation, während die Alternativen einen anderen Zweck haben.":"گزینهٔ „متن علاوه بر رنگ“ وضعیت توصیف‌شده را حل می‌کند، در حالی که گزینه‌های دیگر هدف دیگری دارند.","Semantische Elemente wie `button` unterstützen Tastatur und Vorleseprogramme.":"عنصرهای معنایی مثل `button` از کیبورد و برنامه‌های صفحه‌خوان پشتیبانی می‌کنند.","Wichtige Bilder brauchen einen passenden Alternativtext, nicht bloß eine Farbe.":"عکس‌های مهم به یک متن جایگزین مناسب نیاز دارند، نه فقط یک رنگ.","Projekt: Vereinsseite":"پروژه: صفحهٔ انجمن","Eine zugängliche responsive Vereinsseite erstellen.":"یک صفحهٔ انجمن دسترس‌پذیر و واکنش‌گرا بسازید.","Vereinsnamen und Angebot zeigen":"نشان دادن نام انجمن و برنامه‌ها","Ein Verein möchte neue Mitglieder begrüßen. Die Startseite braucht einen Namen und eine kurze Beschreibung. Verwende dafür eine h1 und einen Absatz. Besucher sollen sofort verstehen, worum es geht. Eine Vereinsseite ist die digitale Eingangstür für neue Mitglieder.":"یک انجمن می‌خواهد به اعضای تازه خوش‌آمد بگوید. صفحهٔ اول به یک نام و یک توضیح کوتاه نیاز دارد. برای این کار یک h1 و یک پاراگراف به کار ببرید. بازدیدکنندگان باید فوراً بفهمند که موضوع چیست. صفحهٔ یک انجمن دروازهٔ دیجیتالی برای اعضای تازه است.","Die Überschrift nennt den Verein und der Absatz die Aktivität.":"عنوان نام انجمن و پاراگراف فعالیت را نام می‌برد.","Kontaktziel verlinken":"لینک دادن به بخش تماس","Eine Navigation führt zu Angeboten und Kontakt. Verwende dafür echte Links mit sinnvollen Namen. Die Ziele müssen im Dokument existieren. So bleiben die Wege verständlich. Der Kontaktlink sollte einen klaren Namen tragen.":"یک منو به برنامه‌ها و تماس می‌برد. برای این کار لینک‌های واقعی با نام‌های معقول به کار ببرید. هدف‌ها باید در سند وجود داشته باشند. به این ترتیب راه‌ها قابل فهم می‌مانند. لینک تماس باید یک نام روشن داشته باشد.","Der Link springt zum Abschnitt mit id kontakt.":"لینک به بخشی با id برابر kontakt می‌پرد.","Angebote als Raster gestalten":"طراحی برنامه‌ها به شکل شبکه","Gestalte Karten für die Angebote. CSS Grid sorgt auf großen Bildschirmen für Spalten. Auf dem Handy bleiben die Karten untereinander. Gib jeder Karte ausreichend Innenabstand. Ein Kartenraster trennt Angebote, ohne Informationen zu verstecken.":"برای برنامه‌ها کارت طراحی کنید. CSS Grid در صفحه‌های بزرگ ستون می‌سازد. در موبایل کارت‌ها زیر هم می‌مانند. به هر کارت فاصلهٔ داخلی کافی بدهید. یک شبکهٔ کارت برنامه‌ها را جدا می‌کند، بدون اینکه معلوماتی را پنهان کند.","Das Raster trennt die Angebote sichtbar.":"شبکه برنامه‌ها را به‌طور قابل دید جدا می‌کند.","Tastatur und Handy prüfen":"بررسی کیبورد و موبایل","Prüfe am Ende die Tastatur und das Handyformat. Eine Kontaktmöglichkeit muss klar erkennbar sein. Nutze gut lesbare Farben und Beschriftungen. Erst danach übergibst du die Seite an das Code-Studio. Probiere das Projekt mit Tastatur und schmaler Handyansicht aus.":"در آخر کیبورد و قالب موبایل را بررسی کنید. یک راه تماس باید روشن قابل شناخت باشد. رنگ‌ها و برچسب‌های خوانا به کار ببرید. فقط بعد از آن صفحه را به استودیوی کد بسپارید. پروژه را با کیبورد و نمای باریک موبایل امتحان کنید.","Der Kontaktabschnitt ist das Ziel des Navigationslinks.":"بخش تماس هدف لینک منو است.","Linkziel #kontakt ohne passenden Abschnitt":"هدف لینک #kontakt بدون بخش مناسب","Wenn der Kontaktlink beim Anklicken nicht zum Abschnitt springt, fehlt die passende ID. Verbinde `<a href=\"#kontakt\">Kontakt</a>` mit `<section id=\"kontakt\">...</section>`.":"اگر لینک تماس با کلیک به بخش مربوط نپرد، ID مناسب کم است. `<a href=\"#kontakt\">Kontakt</a>` را با `<section id=\"kontakt\">...</section>` وصل کنید.","Karten ohne Umbruch auf schmalem Bildschirm":"کارت‌ها بدون شکستن در صفحهٔ باریک","Wenn Angebotskarten auf einem kleinen Display nebeneinander gequetscht werden, fehlt die mobile Grundregel. Nutze `main { display: grid; grid-template-columns: 1fr; }` und ergänze größere Spalten erst per Media Query.":"اگر کارت‌های برنامه در یک صفحهٔ کوچک کنار هم فشرده شوند، قاعدهٔ پایهٔ موبایل کم است. `main { display: grid; grid-template-columns: 1fr; }` را به کار ببرید و ستون‌های بزرگ‌تر را فقط با Media Query اضافه کنید.","Welcher Link springt zum Kontaktabschnitt?":"کدام لینک به بخش تماس می‌پرد؟","Bei „Welcher Link springt zum Kontaktabschnitt?“ ist „<a href=\"#kontakt\">Kontakt</a>“ die passende Wahl, weil sie die gerade geübte Regel korrekt benennt.":"در سوال «کدام لینک به بخش تماس می‌پرد؟» گزینهٔ „<a href=\"#kontakt\">Kontakt</a>“ درست است، چون قاعده‌ای را که همین حالا تمرین شد درست نام می‌برد.","Was gehört zu einer guten Startseite?":"چه چیزی به یک صفحهٔ اول خوب تعلق دارد؟","Nur dekorative Bilder":"فقط عکس‌های تزئینی","Nur ein leeres Menü":"فقط یک منوی خالی","Name und verständliche Beschreibung":"نام و یک توضیح قابل فهم","Für diese Aufgabe passt „Name und verständliche Beschreibung“; die beiden anderen Möglichkeiten erfüllen die gefragte Funktion nicht.":"برای این کار „نام و یک توضیح قابل فهم“ درست است؛ دو گزینهٔ دیگر کار خواسته‌شده را انجام نمی‌دهند.","Was prüfst du vor der Veröffentlichung?":"پیش از نشر چه چیزی را بررسی می‌کنید؟","Handyansicht und Tastatur":"نمای موبایل و کیبورد","Nur die PC-Ansicht":"فقط نمای کمپیوتر","Nur die Schriftfarbe":"فقط رنگ متن","Die Auswahl „Handyansicht und Tastatur“ löst die beschriebene Situation, während die Alternativen einen anderen Zweck haben.":"گزینهٔ „نمای موبایل و کیبورد“ وضعیت توصیف‌شده را حل می‌کند، در حالی که گزینه‌های دیگر هدف دیگری دارند.","Ein Kontaktlink mit `#kontakt` braucht ein Ziel mit `id=\"kontakt\"`.":"یک لینک تماس با `#kontakt` به یک هدف با `id=\"kontakt\"` نیاز دارد.","Prüfe das fertige Projekt mit Tastatur, Handybreite und verständlichen Texten.":"پروژهٔ آماده را با کیبورد، پهنای موبایل و متن‌های قابل فهم بررسی کنید.","CSS steht für Cascading Style Sheets. Eine CSS-Regel besteht aus einem Selektor, der bestimmt, welche Elemente gemeint sind, und einem Deklarationsblock in geschweiften Klammern mit Eigenschaft und Wert, etwa `color: red;`. Der Browser liest das HTML, baut daraus einen Baum von Elementen und wendet dann alle passenden Regeln an.":"CSS یعنی Cascading Style Sheets (برگه‌های سبک آبشاری). یک قاعدهٔ CSS از یک انتخابگر تشکیل شده که تعیین می‌کند کدام عنصرها منظورند، و یک بلوک اعلان داخل آکولاد با ویژگی و مقدار، مثلاً `color: red;`. مرورگر HTML را می‌خواند، از آن درختی از عنصرها می‌سازد و بعد همهٔ قاعده‌های مناسب را اعمال می‌کند.","Ein Element darf mehrere Klassen gleichzeitig tragen, getrennt durch Leerzeichen: `class=\"hinweis wichtig\"`. So kombinierst du Bausteine, etwa eine Grundgestaltung und eine Farbvariante. Klassennamen sollten beschreiben, was etwas ist (`hinweis`), nicht wie es aussieht (`rot`), damit sie auch nach einer Farbänderung noch passen.":"یک عنصر می‌تواند همزمان چند کلاس داشته باشد که با فاصله جدا می‌شوند: `class=\"hinweis wichtig\"`. به این ترتیب قطعه‌ها را ترکیب می‌کنید، مثلاً یک طراحی پایه و یک گونهٔ رنگی. نام کلاس‌ها باید بگویند چیزی چیست (`hinweis`)، نه اینکه چه شکلی دارد (`rot`)، تا بعد از تغییر رنگ هم مناسب بمانند.","Wenn mehrere Regeln dasselbe Element betreffen, entscheidet die Spezifität: ID-Selektoren wiegen am meisten, dann Klassen, dann einfache Elementnamen wie `p`. Bei gleicher Spezifität gewinnt die Regel, die weiter unten steht. Das ist das „Cascading“ – die Kaskade – im Namen CSS.":"وقتی چند قاعده همان عنصر را هدف می‌گیرند، ویژگی‌مندی (Specificity) تصمیم می‌گیرد: انتخابگرهای ID بیشترین وزن را دارند، بعد کلاس‌ها، بعد نام‌های سادهٔ عنصر مثل `p`. در ویژگی‌مندی برابر، قاعده‌ای برنده است که پایین‌تر آمده است. این همان «آبشار» (Cascading) در نام CSS است.","Selektoren lassen sich kombinieren: `article .hinweis` trifft nur Hinweise innerhalb eines Artikels, `p.hinweis` nur Absätze mit dieser Klasse. Mit `:hover` reagierst du auf die Maus, mit `:focus` auf die Tastatur. Die Entwicklerwerkzeuge des Browsers (F12) zeigen dir für jedes Element, welche Regeln gelten und welche überschrieben wurden.":"انتخابگرها را می‌توان ترکیب کرد: `article .hinweis` فقط راهنماهای داخل یک مقاله را می‌گیرد و `p.hinweis` فقط پاراگراف‌هایی با این کلاس را. با `:hover` به ماوس و با `:focus` به کیبورد واکنش نشان می‌دهید. ابزار توسعه‌دهندهٔ مرورگر (F12) برای هر عنصر نشان می‌دهد کدام قاعده‌ها اعتبار دارند و کدام بازنویسی شده‌اند.","Eine ID muss auf einer Seite eindeutig sein, weil sie auch für Sprungmarken (`href=\"#kontakt\"`), Formularbeschriftungen und JavaScript benutzt wird. Doppelte IDs führen zu schwer erklärbaren Fehlern. Für Gestaltung sind Klassen deshalb fast immer die bessere Wahl.":"یک ID باید در صفحه یکتا باشد، چون برای پرش به بخش‌ها (`href=\"#kontakt\"`)، برچسب‌های فرم و JavaScript هم به کار می‌رود. ID های تکراری به خطاهای سخت‌توضیح می‌رسند. به همین دلیل برای طراحی، کلاس‌ها تقریباً همیشه انتخاب بهتری هستند.","Weil eine ID-Regel sehr spezifisch ist, lässt sie sich später nur mit noch spezifischeren Regeln überschreiben. Große Projekte vermeiden deshalb ID-Selektoren im CSS ganz. Groß- und Kleinschreibung zählt: `#Kontakt` und `#kontakt` sind verschiedene IDs.":"چون یک قاعدهٔ ID بسیار ویژه است، بعداً فقط با قاعده‌های باز هم ویژه‌تر می‌توان آن را بازنویسی کرد. به همین دلیل پروژه‌های بزرگ از انتخابگرهای ID در CSS کاملاً پرهیز می‌کنند. حروف بزرگ و کوچک مهم‌اند: `#Kontakt` و `#kontakt` دو ID متفاوت‌اند.","Wiederverwendbare Klassen sind die Grundlage jedes Designsystems. Statt jede Stelle einzeln zu gestalten, legst du einmal fest, wie ein Hinweis aussieht, und vergibst die Klasse überall. Änderst du die Farbe, ändern sich alle Hinweise auf einmal.":"کلاس‌های قابل استفادهٔ دوباره پایهٔ هر سیستم طراحی هستند. به جای اینکه هر جا را جداگانه طراحی کنید، یک بار تعیین می‌کنید یک راهنما چه شکلی دارد و کلاس را همه‌جا می‌دهید. اگر رنگ را عوض کنید، همهٔ راهنماها یک‌جا تغییر می‌کنند.","Viele Teams benennen Klassen nach festen Regeln, zum Beispiel nach BEM (Block, Element, Modifier): `karte`, `karte__titel`, `karte--hervorgehoben`. Solche Konventionen machen großen Code verständlich, weil man am Namen erkennt, wozu eine Klasse gehört.":"بسیاری از تیم‌ها کلاس‌ها را بر اساس قاعده‌های ثابت نام‌گذاری می‌کنند، مثلاً بر اساس BEM (بلوک، عنصر، اصلاح‌کننده): `karte`، `karte__titel`، `karte--hervorgehoben`. چنین قراردادهایی کد بزرگ را قابل فهم می‌کنند، چون از نام می‌فهمید یک کلاس به چه چیزی تعلق دارد.","Jedes HTML-Element ist für den Browser ein Rechteck aus vier Schichten: Inhalt, Innenabstand (padding), Rahmen (border) und Außenabstand (margin). Dieses Box-Modell ist die Grundlage jedes Layouts. Die Entwicklerwerkzeuge zeigen die vier Schichten farbig an, wenn du ein Element auswählst.":"هر عنصر HTML برای مرورگر یک مستطیل از چهار لایه است: محتوا، فاصلهٔ داخلی (padding)، حاشیه (border) و فاصلهٔ بیرونی (margin). این مدل جعبه پایهٔ هر چیدمان است. ابزار توسعه‌دهنده وقتی یک عنصر را انتخاب کنید، چهار لایه را رنگی نشان می‌دهد.","padding nimmt die Hintergrundfarbe des Elements an, margin ist immer durchsichtig. Du kannst die Werte einzeln setzen (`padding-top`) oder als Kurzform: `padding: 10px 20px;` bedeutet oben und unten 10, links und rechts 20 Pixel. Bei vier Werten gilt die Reihenfolge oben, rechts, unten, links – im Uhrzeigersinn.":"padding رنگ پس‌زمینهٔ عنصر را می‌گیرد و margin همیشه شفاف است. می‌توانید مقدارها را جداگانه بدهید (`padding-top`) یا به شکل کوتاه: `padding: 10px 20px;` یعنی بالا و پایین 10 و چپ و راست 20 پیکسل. در چهار مقدار ترتیب بالا، راست، پایین، چپ است – در جهت عقربه‌های ساعت.","Die Kurzform `border: 2px solid #333;` setzt Breite, Linienart und Farbe auf einmal. Weitere Linienarten sind `dashed` (gestrichelt) und `dotted` (gepunktet). Mit `border-radius` rundest du die Ecken ab; `border-radius: 50%` macht aus einem Quadrat einen Kreis.":"شکل کوتاه `border: 2px solid #333;` پهنا، نوع خط و رنگ را یک‌جا تعیین می‌کند. نوع‌های دیگر خط `dashed` (خط‌چین) و `dotted` (نقطه‌چین) هستند. با `border-radius` گوشه‌ها را گرد می‌کنید؛ `border-radius: 50%` از یک مربع یک دایره می‌سازد.","Ein Rahmen nimmt Platz ein und vergrößert das Element, wenn nicht border-box gilt. Willst du nur zur Fehlersuche sehen, wo ein Element liegt, nimm `outline`: Die Umrandung wird gezeichnet, verändert aber das Layout nicht.":"یک حاشیه جا می‌گیرد و اگر border-box نباشد عنصر را بزرگ‌تر می‌کند. اگر فقط برای پیدا کردن خطا بخواهید ببینید یک عنصر کجاست، از `outline` استفاده کنید: دورخط رسم می‌شود، اما چیدمان را تغییر نمی‌دهد.","Vertikale Außenabstände benachbarter Elemente fallen zusammen: Hat eine Karte unten 20 Pixel und die nächste oben 30 Pixel margin, beträgt der Abstand 30, nicht 50 Pixel. Dieses Verhalten heißt Margin Collapsing und überrascht viele Anfänger. In Flexbox- und Grid-Layouts tritt es nicht auf.":"فاصله‌های بیرونی عمودی عنصرهای همسایه روی هم می‌افتند: اگر یک کارت پایین 20 پیکسل و کارت بعدی بالا 30 پیکسل margin داشته باشد، فاصله 30 است، نه 50 پیکسل. این رفتار را Margin Collapsing می‌نامند و بسیاری از تازه‌کارها را غافلگیر می‌کند. در چیدمان‌های Flexbox و Grid پیش نمی‌آید.","Mit `margin: 0 auto;` zentrierst du ein Element mit fester Breite waagerecht, weil der Browser den freien Platz links und rechts gleich verteilt. In modernen Layouts ersetzt die Eigenschaft `gap` oft einzelne Außenabstände, weil sie nur zwischen Elementen wirkt und nicht am Rand.":"با `margin: 0 auto;` یک عنصر با پهنای ثابت را افقی وسط می‌گذارید، چون مرورگر جای خالی چپ و راست را برابر تقسیم می‌کند. در چیدمان‌های امروزی ویژگی `gap` اغلب جای فاصله‌های بیرونی جداگانه را می‌گیرد، چون فقط بین عنصرها اثر دارد و نه در لبه.","Ohne Angabe gilt `box-sizing: content-box`: Die eingestellte Breite betrifft nur den Inhalt. Eine Karte mit `width: 300px`, 20 Pixel padding auf jeder Seite und 2 Pixel Rahmen ist dann in Wirklichkeit 344 Pixel breit. Mit border-box bleibt sie genau 300 Pixel breit.":"بدون مشخصه `box-sizing: content-box` اعتبار دارد: پهنای تعیین‌شده فقط به محتوا مربوط است. یک کارت با `width: 300px`، 20 پیکسل padding در هر طرف و 2 پیکسل حاشیه در واقع 344 پیکسل پهنا دارد. با border-box دقیقاً 300 پیکسل می‌ماند.","Darum beginnen viele Stylesheets mit der Regel `*, *::before, *::after { box-sizing: border-box; }`. Sie gilt dann für alle Elemente der Seite. Das macht Breitenberechnungen vorhersehbar und verhindert, dass Inhalte auf schmalen Bildschirmen über den Rand ragen.":"به همین دلیل بسیاری از برگه‌های سبک با قاعدهٔ `*, *::before, *::after { box-sizing: border-box; }` شروع می‌شوند. این قاعده آن وقت برای همهٔ عنصرهای صفحه اعتبار دارد. حساب پهنا را قابل پیش‌بینی می‌کند و جلوی بیرون زدن محتوا از لبه در صفحه‌های باریک را می‌گیرد.","Mit `display: flex` wird ein Element zum Flex-Container, seine direkten Kinder werden zu Flex-Elementen. Standardmäßig stehen sie dann nebeneinander in einer Zeile. Enkel-Elemente sind davon nicht betroffen – für sie bräuchtest du einen eigenen Flex-Container.":"با `display: flex` یک عنصر به ظرف Flex تبدیل می‌شود و فرزندان مستقیمش عنصرهای Flex می‌شوند. به‌طور پیش‌فرض آن وقت در یک سطر کنار هم قرار می‌گیرند. نوه‌ها تحت تأثیر نیستند – برای آن‌ها یک ظرف Flex جداگانه لازم دارید.","Flexbox ist ein eindimensionales Layoutsystem: Es ordnet Elemente entlang einer Achse an, entweder als Zeile (`flex-direction: row`) oder als Spalte (`column`). Für Navigationen, Werkzeugleisten und das Ausrichten von Elementen innerhalb einer Karte ist es die erste Wahl.":"Flexbox یک سیستم چیدمان یک‌بعدی است: عنصرها را در امتداد یک محور مرتب می‌کند، یا به شکل سطر (`flex-direction: row`) یا ستون (`column`). برای نوارهای ناوبری، نوارابزارها و تراز کردن عنصرها داخل یک کارت انتخاب اول است.","`gap` wirkt nur zwischen den Elementen, nicht vor dem ersten und nach dem letzten. Bei margin entstünden dagegen zusätzliche Abstände am Rand, die man mühsam wieder entfernen müsste. Mit `gap: 10px 20px` setzt du Zeilen- und Spaltenabstand getrennt.":"`gap` فقط بین عنصرها اثر دارد، نه پیش از اولی و بعد از آخری. با margin فاصله‌های اضافی در لبه پیش می‌آمد که باید با زحمت دوباره حذف می‌شد. با `gap: 10px 20px` فاصلهٔ سطر و ستون را جدا تعیین می‌کنید.","Damit Links gut antippbar sind, sollten sie nicht zu klein sein; Richtlinien für Barrierefreiheit empfehlen Tippflächen von mindestens etwa 24 mal 24 Pixeln, besser 44 Pixel. Gib Links dafür etwas padding. Der Abstand durch gap verhindert zusätzlich, dass man versehentlich den Nachbarn trifft.":"برای اینکه لینک‌ها خوب لمس‌شدنی باشند، نباید خیلی کوچک باشند؛ رهنمودهای دسترس‌پذیری سطح لمس حداقل حدود 24 در 24 پیکسل، بهتر 44 پیکسل را توصیه می‌کنند. برای آن به لینک‌ها کمی padding بدهید. فاصلهٔ gap علاوه بر آن جلوی لمس اشتباهی همسایه را می‌گیرد.","Die Hauptachse folgt der Richtung von `flex-direction`, die Querachse steht senkrecht dazu. `justify-content` verteilt entlang der Hauptachse (`flex-start`, `center`, `space-between`, `space-around`), `align-items` richtet entlang der Querachse aus (`stretch`, `center`, `flex-start`).":"محور اصلی جهت `flex-direction` را دنبال می‌کند و محور عرضی بر آن عمود است. `justify-content` در امتداد محور اصلی تقسیم می‌کند (`flex-start`، `center`، `space-between`، `space-around`) و `align-items` در امتداد محور عرضی تراز می‌کند (`stretch`، `center`، `flex-start`).","Mit `flex-direction: column` tauschen die Achsen ihre Rollen: Dann verteilt `justify-content` senkrecht. Das verwirrt anfangs, ist aber logisch. Ein klassischer Trick: `display: flex; justify-content: center; align-items: center;` zentriert ein Element in beide Richtungen.":"با `flex-direction: column` محورها نقششان را عوض می‌کنند: آن وقت `justify-content` عمودی تقسیم می‌کند. این اول گیج‌کننده است، اما منطقی است. یک ترفند کلاسیک: `display: flex; justify-content: center; align-items: center;` یک عنصر را در هر دو جهت وسط می‌گذارد.","Ohne `flex-wrap: wrap` versucht Flexbox, alle Elemente in eine Zeile zu quetschen; sie werden schmaler oder ragen über den Rand. Mit wrap entstehen bei Bedarf weitere Zeilen. So bleibt die Navigation auch auf kleinen Bildschirmen vollständig.":"بدون `flex-wrap: wrap` Flexbox تلاش می‌کند همهٔ عنصرها را در یک سطر فشرده کند؛ باریک‌تر می‌شوند یا از لبه بیرون می‌زنند. با wrap در صورت نیاز سطرهای بیشتری ساخته می‌شوند. به این ترتیب نوار ناوبری در صفحه‌های کوچک هم کامل می‌ماند.","Mit der Eigenschaft `flex` steuerst du, wie Elemente wachsen und schrumpfen: `flex: 1` lässt ein Element den freien Platz füllen. Für sehr viele Menüpunkte auf dem Handy nutzt man oft ein ausklappbares Menü; die Grundlage bleibt aber eine sauber umbrechende Liste.":"با ویژگی `flex` تعیین می‌کنید عنصرها چطور بزرگ و کوچک شوند: `flex: 1` می‌گذارد یک عنصر جای خالی را پر کند. برای منوهای خیلی زیاد در گوشی اغلب از یک منوی بازشونده استفاده می‌کنند؛ اما پایه همچنان یک لیست تمیز با شکستن سطر است.","Grid ist ein zweidimensionales Layoutsystem: Es ordnet Elemente gleichzeitig in Zeilen und Spalten an. Damit eignet es sich für ganze Seitenbereiche, Bildergalerien und Kartenraster. Flexbox und Grid ergänzen sich: Grid für das große Gerüst, Flexbox für die Ausrichtung im Kleinen.":"Grid یک سیستم چیدمان دوبعدی است: عنصرها را همزمان در سطرها و ستون‌ها مرتب می‌کند. به همین دلیل برای بخش‌های کامل صفحه، گالری عکس و شبکهٔ کارت‌ها مناسب است. Flexbox و Grid همدیگر را کامل می‌کنند: Grid برای چارچوب بزرگ و Flexbox برای تراز کردن در مقیاس کوچک.","Wie bei Flexbox wirkt `display: grid` nur auf die direkten Kinder. Ohne weitere Angaben entsteht zunächst ein Raster mit nur einer Spalte, in dem die Kinder untereinanderstehen. Erst `grid-template-columns` erzeugt mehrere Spalten.":"مثل Flexbox، `display: grid` فقط روی فرزندان مستقیم اثر دارد. بدون مشخصهٔ بیشتر اول یک شبکه با فقط یک ستون ساخته می‌شود که فرزندان در آن زیر هم قرار می‌گیرند. تازه `grid-template-columns` چند ستون می‌سازد.","Die Einheit `fr` (fraction, Bruchteil) verteilt den freien Platz nach Anteilen. `1fr 2fr` ergibt eine schmale und eine doppelt so breite Spalte. Du kannst fr auch mit festen Werten mischen, etwa `200px 1fr` für eine feste Seitenleiste und einen flexiblen Hauptbereich.":"واحد `fr` (fraction، کسر) جای خالی را بر اساس سهم تقسیم می‌کند. `1fr 2fr` یک ستون باریک و یک ستون دو برابر پهن می‌دهد. می‌توانید fr را با مقدارهای ثابت هم مخلوط کنید، مثلاً `200px 1fr` برای یک نوار کناری ثابت و یک بخش اصلی انعطاف‌پذیر.","Für viele gleiche Spalten gibt es `repeat`: `repeat(3, 1fr)` statt `1fr 1fr 1fr`. Besonders praktisch ist `repeat(auto-fit, minmax(200px, 1fr))`: Der Browser setzt so viele Spalten, wie mit mindestens 200 Pixeln Breite hineinpassen – ganz ohne Media Query.":"برای ستون‌های یکسان زیاد `repeat` هست: `repeat(3, 1fr)` به جای `1fr 1fr 1fr`. به‌خصوص `repeat(auto-fit, minmax(200px, 1fr))` مفید است: مرورگر آن قدر ستون می‌گذارد که با حداقل 200 پیکسل پهنا جا شوند – کاملاً بدون Media Query.","`gap` legt die Abstände zwischen den Rasterzellen fest, aber nicht am äußeren Rand. Mit `row-gap` und `column-gap` steuerst du Zeilen- und Spaltenabstand getrennt. Für einen Abstand zum Seitenrand setzt du padding auf den Container.":"`gap` فاصله‌های بین خانه‌های شبکه را تعیین می‌کند، اما نه در لبهٔ بیرونی. با `row-gap` و `column-gap` فاصلهٔ سطر و ستون را جدا تنظیم می‌کنید. برای فاصله تا لبهٔ صفحه به ظرف padding بدهید.","Einzelne Elemente können sich über mehrere Zellen erstrecken: `grid-column: span 2` macht eine Karte doppelt so breit. Mit `grid-template-areas` lassen sich Bereiche sogar mit Namen wie „kopf“, „menue“ und „inhalt“ beschreiben, was große Layouts sehr übersichtlich macht.":"عنصرهای تکی می‌توانند روی چند خانه گسترده شوند: `grid-column: span 2` یک کارت را دو برابر پهن می‌کند. با `grid-template-areas` حتی می‌توان بخش‌ها را با نام‌هایی مثل «سر»، «منو» و «محتوا» توصیف کرد که چیدمان‌های بزرگ را بسیار مرتب می‌کند.","Diese Vorgehensweise heißt Mobile First: Man gestaltet zuerst die einspaltige Handyansicht und ergänzt für größere Bildschirme weitere Spalten. Inzwischen nutzen weltweit mehr Menschen das Internet mit dem Handy als mit dem Computer, deshalb ist diese Reihenfolge sinnvoll.":"این روش را Mobile First (اول موبایل) می‌نامند: اول نمای یک‌ستونی گوشی را طراحی می‌کنند و برای صفحه‌های بزرگ‌تر ستون‌های بیشتری اضافه می‌کنند. اکنون در جهان مردم بیشتر با گوشی تا با کمپیوتر از انترنت استفاده می‌کنند، به همین دلیل این ترتیب معقول است.","Die Reihenfolge im HTML bestimmt auch die Reihenfolge beim Vorlesen und bei der Tastaturbedienung. Grid kann Elemente zwar optisch umsortieren, doch die logische Reihenfolge sollte dabei sinnvoll bleiben, sonst springt der Fokus für Tastaturnutzer verwirrend über die Seite.":"ترتیب در HTML ترتیب بلندخوانی و کار با کیبورد را هم تعیین می‌کند. Grid می‌تواند عنصرها را از نظر دیداری جابه‌جا کند، اما ترتیب منطقی باید معقول بماند، وگرنه فوکوس برای کاربران کیبورد به شکل گیج‌کننده‌ای روی صفحه می‌پرد.","Eine Media Query ist eine Bedingung im CSS: `@media (min-width: 700px) { ... }` – die Regeln in den Klammern gelten nur, wenn das Fenster mindestens 700 Pixel breit ist. Neben der Breite kann man auch die Ausrichtung, den Druck oder die bevorzugte Farbdarstellung abfragen, etwa `prefers-color-scheme: dark`.":"یک Media Query یک شرط در CSS است: `@media (min-width: 700px) { ... }` – قاعده‌های داخل آکولاد فقط وقتی اعتبار دارند که پنجره حداقل 700 پیکسل پهن باشد. کنار پهنا، جهت، چاپ یا نمایش رنگ ترجیحی را هم می‌توان پرسید، مثلاً `prefers-color-scheme: dark`.","Damit Media Queries auf dem Handy richtig funktionieren, braucht jede Seite im Kopfbereich die Zeile `<meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">`. Ohne sie tut das Handy so, als wäre es ein breiter Computerbildschirm, und verkleinert alles.":"برای اینکه Media Query ها روی گوشی درست کار کنند، هر صفحه در بخش سر خط `<meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">` را لازم دارد. بدون آن گوشی وانمود می‌کند که یک صفحهٔ پهن کمپیوتر است و همه چیز را کوچک می‌کند.","Prozentangaben beziehen sich auf die Breite des umgebenden Elements. Dazu gibt es weitere relative Einheiten: `rem` richtet sich nach der Grundschriftgröße, `vw` nach der Fensterbreite. Relative Einheiten passen sich an, wenn Menschen in den Einstellungen größere Schrift wählen.":"مقدارهای درصدی به پهنای عنصر دربرگیرنده مربوط‌اند. کنار آن واحدهای نسبی دیگری هست: `rem` بر اساس اندازهٔ پایهٔ خط و `vw` بر اساس پهنای پنجره. واحدهای نسبی وقتی مردم در تنظیمات خط بزرگ‌تر انتخاب کنند، خودشان را تطبیق می‌دهند.","`max-width: 100%` erlaubt einem Bild, kleiner zu werden, aber nie größer als sein Platz. Ergänze `height: auto`, damit es nicht verzerrt wird. Für scharfe Bilder auf hochauflösenden Displays kann der Browser mit `srcset` automatisch eine passende Bildgröße auswählen.":"`max-width: 100%` به یک عکس اجازه می‌دهد کوچک‌تر شود، اما هرگز بزرگ‌تر از جایش نه. `height: auto` را اضافه کنید تا کج نشود. برای عکس‌های واضح در نمایشگرهای با وضوح بالا، مرورگر می‌تواند با `srcset` خودکار اندازهٔ مناسب عکس را انتخاب کند.","Bei Mobile First stehen die Grundregeln für das Handy ohne Media Query oben, und `min-width`-Abfragen fügen für größere Bildschirme Änderungen hinzu. Die Grenzwerte nennt man Breakpoints. Wähle sie nach deinem Inhalt – dort, wo das Layout unschön wird –, nicht nach einzelnen Gerätemodellen.":"در Mobile First قاعده‌های پایه برای گوشی بدون Media Query در بالا هستند و پرسش‌های `min-width` برای صفحه‌های بزرگ‌تر تغییرها را اضافه می‌کنند. مقدارهای مرزی را Breakpoint می‌نامند. آن‌ها را بر اساس محتوای خود انتخاب کنید – جایی که چیدمان زشت می‌شود – نه بر اساس مدل‌های تکی دستگاه.","Media Queries erhöhen die Spezifität nicht. Darum müssen sie im Stylesheet nach den Grundregeln stehen, sonst überschreiben die Grundregeln sie wieder. Neuere Container Queries reagieren sogar auf die Breite eines Elternelements statt des ganzen Fensters.":"Media Query ها ویژگی‌مندی را بالا نمی‌برند. به همین دلیل باید در برگهٔ سبک بعد از قاعده‌های پایه بیایند، وگرنه قاعده‌های پایه دوباره آن‌ها را بازنویسی می‌کنند. Container Query های تازه‌تر حتی به پهنای یک عنصر والد واکنش نشان می‌دهند، نه کل پنجره.","320 Pixel entsprechen der Breite kleiner Smartphones und sind ein verbreiteter Mindestwert beim Testen. In den Entwicklerwerkzeugen gibt es einen Gerätemodus, mit dem du beliebige Breiten ausprobieren kannst. Auf echten Geräten zu testen, bleibt trotzdem wichtig, etwa wegen der Bildschirmtastatur.":"320 پیکسل پهنای گوشی‌های کوچک است و یک مقدار حداقل رایج در آزمایش است. در ابزار توسعه‌دهنده یک حالت دستگاه هست که با آن می‌توانید هر پهنایی را امتحان کنید. آزمایش روی دستگاه‌های واقعی باز هم مهم است، مثلاً به خاطر کیبورد روی صفحه.","Lange Wörter, wie sie im Deutschen häufig sind, können schmale Spalten sprengen. `overflow-wrap: anywhere` erlaubt dem Browser, notfalls mitten im Wort umzubrechen, und `hyphens: auto` trennt mit Bindestrich, wenn die Seite `lang=\"de\"` angibt. Für gut lesbare Textzeilen auf großen Bildschirmen begrenzt man die Breite auf etwa 60 bis 75 Zeichen.":"کلمه‌های طولانی که در آلمانی رایج‌اند ممکن است ستون‌های باریک را بترکانند. `overflow-wrap: anywhere` به مرورگر اجازه می‌دهد در صورت لزوم وسط کلمه بشکند و `hyphens: auto` با خط تیره جدا می‌کند، اگر صفحه `lang=\"de\"` داشته باشد. برای سطرهای متن خوانا در صفحه‌های بزرگ، پهنا را به حدود 60 تا 75 نویسه محدود می‌کنند.","Ein mit `for` und `id` verknüpftes label hat zwei Vorteile: Vorleseprogramme lesen die Beschriftung vor, sobald das Feld den Fokus bekommt, und ein Klick auf die Beschriftung setzt den Cursor ins Feld. Bei kleinen Kontrollkästchen vergrößert das die Klickfläche deutlich.":"یک label که با `for` و `id` وصل شده دو فایده دارد: برنامه‌های بلندخوان همین که خانه فوکوس بگیرد برچسب را می‌خوانند، و کلیک روی برچسب مکان‌نما را در خانه می‌گذارد. در جعبه‌های انتخاب کوچک این سطح کلیک را به‌طور چشمگیری بزرگ می‌کند.","Alternativ kannst du das Eingabefeld direkt in das label schreiben: `<label>Name <input name=\"name\"></label>`. Ein Platzhaltertext (`placeholder`) ersetzt kein label, weil er beim Tippen verschwindet und oft zu blass ist. Das Attribut `name` bestimmt, unter welchem Namen der Wert beim Absenden übertragen wird.":"به جای آن می‌توانید خانهٔ ورودی را مستقیم داخل label بنویسید: `<label>Name <input name=\"name\"></label>`. یک متن جاگیر (`placeholder`) جای label را نمی‌گیرد، چون در وقت تایپ ناپدید می‌شود و اغلب خیلی کم‌رنگ است. ویژگی `name` تعیین می‌کند مقدار در وقت فرستادن با چه نامی منتقل شود.","HTML kennt viele Eingabetypen: `email`, `tel`, `number`, `date`, `url`, `password`, `checkbox`, `radio` und weitere. Der Browser liefert dazu passende Bedienhilfen, etwa einen Kalender bei `date`. Unbekannte Typen behandelt ein alter Browser einfach wie ein normales Textfeld.":"HTML نوع‌های ورودی زیادی می‌شناسد: `email`، `tel`، `number`، `date`، `url`، `password`، `checkbox`، `radio` و دیگران. مرورگر برای آن‌ها کمک‌های مناسب کار می‌دهد، مثلاً یک تقویم در `date`. یک مرورگر قدیمی نوع‌های ناشناخته را ساده مثل یک خانهٔ متنی عادی رفتار می‌کند.","Mit `autocomplete` hilfst du dem Browser beim automatischen Ausfüllen, zum Beispiel `autocomplete=\"email\"` oder `\"street-address\"`. Das spart Menschen viel Tipparbeit. `inputmode=\"numeric\"` zeigt auf dem Handy die Zifferntastatur, ohne die Prüfung von `type=\"number\"` zu erzwingen.":"با `autocomplete` به مرورگر در پر کردن خودکار کمک می‌کنید، مثلاً `autocomplete=\"email\"` یا `\"street-address\"`. این از تایپ زیاد مردم صرفه‌جویی می‌کند. `inputmode=\"numeric\"` روی گوشی کیبورد عددی را نشان می‌دهد، بدون اینکه بررسی `type=\"number\"` را تحمیل کند.","Weitere Prüfattribute sind `minlength`, `maxlength`, `min`, `max` und `pattern` mit einem regulären Ausdruck. Mit der CSS-Pseudoklasse `:invalid` kannst du ungültige Felder gestalten. Die eingebauten Meldungen formuliert der Browser in der Sprache des Systems.":"ویژگی‌های بررسی دیگر `minlength`، `maxlength`، `min`، `max` و `pattern` با یک عبارت منظم هستند. با شبه‌کلاس CSS به نام `:invalid` می‌توانید خانه‌های نامعتبر را طراحی کنید. مرورگر پیام‌های داخلی را به زبان سیستم می‌نویسد.","Browserprüfungen lassen sich leicht umgehen, etwa über die Entwicklerwerkzeuge oder mit eigenen Anfragen. Ein Server muss deshalb jede Eingabe noch einmal selbst prüfen. Dieser Grundsatz – dem Client nie vertrauen – gehört zu den wichtigsten Regeln der Websicherheit.":"بررسی‌های مرورگر را آسان می‌توان دور زد، مثلاً از راه ابزار توسعه‌دهنده یا با درخواست‌های خودساخته. به همین دلیل یک سرور باید هر ورودی را دوباره خودش بررسی کند. این اصل – هرگز به کلاینت اعتماد نکن – از مهم‌ترین قاعده‌های امنیت وب است.","Ein `button` innerhalb eines Formulars ist ohne Angabe automatisch ein Absende-Knopf. Darum lösen Knöpfe zum Beispiel für „Passwort anzeigen“ versehentlich das Absenden aus, wenn `type=\"button\"` fehlt. Gib den Typ deshalb immer ausdrücklich an.":"یک `button` داخل یک فرم بدون مشخصه خودکار یک دکمهٔ فرستادن است. به همین دلیل دکمه‌هایی مثلاً برای «نشان دادن رمز» به اشتباه فرستادن را شروع می‌کنند، اگر `type=\"button\"` نباشد. پس نوع را همیشه صریح بنویسید.","Drückt man in einem Textfeld Enter, schickt der Browser das Formular ebenfalls ab. Mit JavaScript fängt man das Ereignis `submit` am Formular ab, nicht den Klick auf den Knopf – so funktionieren Maus, Tastatur und Enter gleichermaßen. `event.preventDefault()` verhindert dabei das Neuladen der Seite.":"اگر در یک خانهٔ متنی Enter بزنید، مرورگر فرم را هم می‌فرستد. با JavaScript رویداد `submit` را روی فرم می‌گیرند، نه کلیک روی دکمه را – به این ترتیب ماوس، کیبورد و Enter به یک شکل کار می‌کنند. `event.preventDefault()` در این کار جلوی بار شدن دوبارهٔ صفحه را می‌گیرد.","Ein echter `button` ist automatisch mit Tab erreichbar, lässt sich mit Enter und Leertaste auslösen und wird von Vorleseprogrammen als Schaltfläche angesagt. Ein klickbarer Absatz kann nichts davon. Wer dieses Verhalten selbst nachbauen will, braucht viel zusätzlichen Code und vergisst leicht etwas.":"یک `button` واقعی خودکار با Tab قابل دسترس است، با Enter و Space فعال می‌شود و برنامه‌های بلندخوان آن را دکمه اعلام می‌کنند. یک پاراگراف کلیک‌شدنی هیچ‌کدام از این‌ها را بلد نیست. کسی که بخواهد این رفتار را خودش بسازد، کد اضافی زیادی لازم دارد و آسان چیزی را فراموش می‌کند.","Barrierefreiheit betrifft viele Menschen: Blinde und sehbehinderte Menschen, Menschen mit motorischen Einschränkungen, ältere Menschen, aber auch jeden mit gebrochenem Arm oder grellem Sonnenlicht auf dem Display. International gelten dafür die Richtlinien WCAG; in der EU verpflichtet der European Accessibility Act seit 2025 viele Unternehmen zu barrierefreien Angeboten.":"دسترس‌پذیری بسیاری از مردم را در بر می‌گیرد: نابینایان و کم‌بینایان، کسانی با محدودیت حرکتی، سالمندان، اما همچنین هر کسی با دست شکسته یا نور تند آفتاب روی صفحه. در سطح بین‌المللی رهنمودهای WCAG برای آن اعتبار دارند؛ در اتحادیهٔ اروپا قانون European Accessibility Act از سال 2025 بسیاری از شرکت‌ها را به خدمات دسترس‌پذیر موظف کرده است.","Vorleseprogramme wie NVDA, JAWS oder VoiceOver können eine Liste aller Überschriften anzeigen und direkt zu ihnen springen. Viele blinde Menschen erkunden eine Seite genau so. Überspringst du Ebenen, etwa von h1 direkt zu h4, wirkt die Gliederung lückenhaft.":"برنامه‌های بلندخوان مثل NVDA، JAWS یا VoiceOver می‌توانند فهرستی از همهٔ عنوان‌ها نشان دهند و مستقیم به آن‌ها بپرند. بسیاری از نابینایان یک صفحه را دقیقاً همین طور می‌گردند. اگر سطح‌ها را جا بیندازید، مثلاً از h1 مستقیم به h4، ساختار ناقص به نظر می‌رسد.","Wähle Überschriften nach ihrer Bedeutung, nicht nach ihrer Größe – die Größe stellst du mit CSS ein. Ergänzend helfen Bereichselemente wie `header`, `nav`, `main` und `footer`, die Vorleseprogramme als Landmarken anbieten. So findet man schnell zum Hauptinhalt.":"عنوان‌ها را بر اساس معنایشان انتخاب کنید، نه اندازه‌شان – اندازه را با CSS تنظیم می‌کنید. علاوه بر آن عنصرهای بخش مثل `header`، `nav`، `main` و `footer` کمک می‌کنند که برنامه‌های بلندخوان آن‌ها را به عنوان نشانه‌های راه پیشنهاد می‌کنند. به این ترتیب زود به محتوای اصلی می‌رسید.","Ein guter Alternativtext beschreibt, was das Bild an dieser Stelle aussagt. Beim Foto eines Vereinsfests reicht „Kinder spielen Fußball auf dem Vereinsplatz“. Ist das Bild ein Link, beschreibt der Text das Ziel, etwa „Zur Startseite“. Bildschirmleser sagen ohnehin „Bild“ an.":"یک متن جایگزین خوب توصیف می‌کند که عکس در این جا چه می‌گوید. برای عکس یک جشن انجمن «بچه‌ها روی زمین انجمن فوتبال بازی می‌کنند» کافی است. اگر عکس یک لینک باشد، متن مقصد را توصیف می‌کند، مثلاً «به صفحهٔ اصلی». صفحه‌خوان‌ها خودشان «عکس» را اعلام می‌کنند.","Fehlt das alt-Attribut ganz, lesen manche Programme den Dateinamen vor, etwa „IMG_4711.jpg“. Bei rein dekorativen Bildern sorgt `alt=\"\"` dafür, dass sie übersprungen werden. Diagramme mit vielen Informationen brauchen zusätzlich eine Beschreibung im Text.":"اگر ویژگی alt کاملاً نباشد، بعضی برنامه‌ها نام فایل را می‌خوانند، مثلاً «IMG_4711.jpg». در عکس‌های فقط تزئینی `alt=\"\"` باعث می‌شود رد شوند. نمودارهایی با معلومات زیاد علاوه بر آن یک توضیح در متن لازم دارند.","Etwa jeder zwölfte Mann hat eine Rot-Grün-Sehschwäche. Ein rot markiertes Feld allein ist für ihn kaum von einem grünen zu unterscheiden. Darum gehört zu jeder Fehlermeldung ein Text, der sagt, was falsch ist und wie man es behebt, und gerne ein Symbol.":"تقریباً از هر دوازده مرد یکی ضعف دید سرخ-سبز دارد. یک خانهٔ با رنگ سرخ به تنهایی برای او به سختی از یک خانهٔ سبز قابل تشخیص است. به همین دلیل هر پیام خطا یک متن لازم دارد که بگوید چه چیزی نادرست است و چطور رفع می‌شود، و خوب است یک نشانه هم داشته باشد.","Für normalen Text verlangen die WCAG ein Kontrastverhältnis von mindestens 4,5 zu 1 zwischen Schrift und Hintergrund. Kostenlose Kontrastprüfer zeigen dir den Wert. Achte auch auf einen sichtbaren Fokusrahmen, damit Tastaturnutzer jederzeit sehen, wo sie sich befinden.":"برای متن عادی، WCAG نسبت تضاد حداقل 4.5 به 1 بین خط و پس‌زمینه را می‌خواهد. بررسی‌کننده‌های رایگان تضاد مقدار را به شما نشان می‌دهند. به یک قاب فوکوس دیدنی هم توجه کنید تا کاربران کیبورد همیشه ببینند کجا هستند.","Planen hilft: Lege vor dem Programmieren fest, welche Bereiche die Seite braucht, zum Beispiel Kopf mit Namen, Angebote, Termine und Kontakt. Eine einfache Skizze auf Papier, Wireframe genannt, zeigt die Anordnung ohne Farben und Details.":"برنامه‌ریزی کمک می‌کند: پیش از برنامه‌نویسی تعیین کنید صفحه کدام بخش‌ها را لازم دارد، مثلاً سر با نام، پیشنهادها، وقت‌ها و تماس. یک طرح سادهٔ روی کاغذ به نام Wireframe چیدمان را بدون رنگ و جزئیات نشان می‌دهد.","Der Inhalt von `title` im Kopfbereich erscheint im Browser-Tab und in Suchergebnissen, die `meta`-Beschreibung oft als Vorschautext. Beide sollten kurz sagen, worum es geht. Eine klare h1 mit dem Vereinsnamen hilft Menschen und Suchmaschinen gleichermaßen.":"محتوای `title` در بخش سر در زبانهٔ مرورگر و در نتیجه‌های جستجو می‌آید و توضیح `meta` اغلب به عنوان متن پیش‌نمایش. هر دو باید کوتاه بگویند موضوع چیست. یک h1 روشن با نام انجمن به انسان‌ها و موتورهای جستجو به یک اندازه کمک می‌کند.","Ein Link mit `#kontakt` springt zum Element mit `id=\"kontakt\"` auf derselben Seite. Mit der CSS-Regel `html { scroll-behavior: smooth; }` scrollt der Browser sanft dorthin. Für Menschen, die Bewegungen schlecht vertragen, schaltet man das mit `prefers-reduced-motion` wieder ab.":"یک لینک با `#kontakt` به عنصری با `id=\"kontakt\"` در همان صفحه می‌پرد. با قاعدهٔ CSS به نام `html { scroll-behavior: smooth; }` مرورگر نرم به آنجا اسکرول می‌کند. برای کسانی که حرکت را بد تحمل می‌کنند، این را با `prefers-reduced-motion` دوباره خاموش می‌کنند.","Linktexte sollten auch ohne Umgebung verständlich sein. „Hier klicken“ sagt in einer Linkliste eines Vorleseprogramms nichts aus, „Zum Kontaktformular“ dagegen schon. Links zu anderen Seiten öffnen sich am besten im selben Tab, damit die Zurück-Taste wie erwartet funktioniert.":"متن لینک‌ها باید بدون اطراف هم قابل فهم باشند. «اینجا کلیک کنید» در فهرست لینک‌های یک برنامهٔ بلندخوان چیزی نمی‌گوید، اما «به فرم تماس» می‌گوید. لینک‌ها به صفحه‌های دیگر بهتر است در همان زبانه باز شوند تا دکمهٔ برگشت طبق انتظار کار کند.","Jede Angebotskarte kann ein `article`-Element mit eigener Überschrift sein. Mit `repeat(auto-fit, minmax(240px, 1fr))` ordnet das Raster die Karten automatisch in so viele Spalten an, wie Platz ist. Gleich hohe Karten entstehen in Grid von selbst.":"هر کارت پیشنهاد می‌تواند یک عنصر `article` با عنوان خودش باشد. با `repeat(auto-fit, minmax(240px, 1fr))` شبکه کارت‌ها را خودکار در آن تعداد ستون که جا هست مرتب می‌کند. کارت‌های هم‌قد در Grid خودشان ساخته می‌شوند.","Bilder in Karten sollten ein festes Seitenverhältnis haben, damit das Raster ruhig wirkt: `aspect-ratio: 4 / 3` zusammen mit `object-fit: cover` schneidet Fotos passend zu, ohne sie zu verzerren. Mit `loading=\"lazy\"` lädt der Browser Bilder erst, wenn sie in die Nähe des sichtbaren Bereichs kommen.":"عکس‌ها در کارت‌ها باید نسبت ابعاد ثابت داشته باشند تا شبکه آرام به نظر برسد: `aspect-ratio: 4 / 3` همراه با `object-fit: cover` عکس‌ها را مناسب برش می‌دهد، بدون اینکه کج شوند. با `loading=\"lazy\"` مرورگر عکس‌ها را تازه وقتی بار می‌کند که نزدیک بخش دیدنی بیایند.","Ein vollständiger Abschlusstest umfasst: alle Links anklicken, die Seite nur mit Tab, Enter und Leertaste bedienen, Breiten von 320 Pixeln bis Desktop prüfen und die Kontraste kontrollieren. Das kostenlose Werkzeug Lighthouse in Chrome erstellt dazu automatisch einen Bericht über Barrierefreiheit und Ladezeit.":"یک آزمون پایانی کامل شامل این‌هاست: کلیک روی همهٔ لینک‌ها، کار با صفحه فقط با Tab، Enter و Space، بررسی پهناها از 320 پیکسل تا رومیزی و کنترول تضادها. ابزار رایگان Lighthouse در Chrome برای این کار خودکار گزارشی دربارهٔ دسترس‌پذیری و زمان بار شدن می‌سازد.","Automatische Prüfungen finden nur einen Teil der Probleme. Am aussagekräftigsten ist es, jemanden die Seite ausprobieren zu lassen, der sie noch nicht kennt. Beobachte dabei, wo die Person zögert – genau dort lohnt sich eine Verbesserung.":"بررسی‌های خودکار فقط بخشی از مشکلات را پیدا می‌کنند. گویاترین کار این است که بگذارید کسی که صفحه را هنوز نمی‌شناسد آن را امتحان کند. ببینید آن شخص کجا مکث می‌کند – دقیقاً آنجا بهبود ارزشش را دارد."};})(typeof window!=="undefined"?window:globalThis);
